function setPublicDataLoading(isLoading) {
  state.publicDataLoading = Boolean(isLoading);
  if (els?.publicDataLoading) {
    els.publicDataLoading.hidden = !state.publicDataLoading || els.mapScreen?.hidden;
  }
}

function finishPublicDataLoading() {
  state.publicDataReady = true;
  setPublicDataLoading(false);
}

