function pointOnPath(points, ratio) {
  const lengths = [];
  let total = 0;
  for (let i = 0; i < points.length - 1; i += 1) {
    const [x1, y1] = points[i];
    const [x2, y2] = points[i + 1];
    const length = Math.hypot(x2 - x1, y2 - y1);
    lengths.push(length);
    total += length;
  }
  let target = total * Math.min(1, Math.max(0, ratio));
  for (let i = 0; i < lengths.length; i += 1) {
    if (target <= lengths[i]) {
      const [x1, y1] = points[i];
      const [x2, y2] = points[i + 1];
      const t = target / lengths[i];
      return [x1 + (x2 - x1) * t, y1 + (y2 - y1) * t];
    }
    target -= lengths[i];
  }
  return points.at(-1);
}

function segmentAtRatio(points, ratio) {
  const lengths = [];
  let total = 0;
  for (let i = 0; i < points.length - 1; i += 1) {
    const [x1, y1] = points[i];
    const [x2, y2] = points[i + 1];
    const length = Math.hypot(x2 - x1, y2 - y1);
    lengths.push(length);
    total += length;
  }

  let target = total * Math.min(1, Math.max(0, ratio));
  for (let i = 0; i < lengths.length; i += 1) {
    if (target <= lengths[i]) return [points[i], points[i + 1]];
    target -= lengths[i];
  }
  return [points.at(-2), points.at(-1)];
}

function normalAtRatio(points, ratio) {
  const [[x1, y1], [x2, y2]] = segmentAtRatio(points, ratio);
  const dx = x2 - x1;
  const dy = y2 - y1;
  const length = Math.hypot(dx, dy) || 1;
  return [-dy / length, dx / length];
}

function svgPath(points) {
  return points.map(([x, y], index) => `${index ? "L" : "M"} ${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
}

// Trim only the painted road, never its geographic endpoints or station positions.
function insetRouteStroke(points, inset) {
  const distances = [0];
  for (let i = 1; i < points.length; i++) {
    distances.push(distances[i - 1] + Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]));
  }
  const total = distances.at(-1);
  if (!total) return points.map(point => [...point]);
  const trim = Math.min(inset, total / 4);
  return [pointOnPath(points, trim / total),
    ...points.filter((point, i) => distances[i] > trim && distances[i] < total - trim),
    pointOnPath(points, 1 - trim / total)];
}

function routeSegmentPoints(points, start, end) {
  const steps = Math.max(8, Math.ceil(Math.abs(end - start) * 28));
  return Array.from({ length: steps + 1 }, (_, index) => pointOnPath(points, start + ((end - start) * index) / steps));
}

function routeVisualPoints(highway) {
  const points = ROUTE_PATHS[highway] || ROUTE_PATHS["경부고속도로"];
  return points.map(([x, y]) => [x, y + ROUTE_VISUAL_OFFSET_Y]);
}

function directionScore(station, targetDirection) {
  const direction = station.direction || "";
  if (!direction) return 0;
  if (direction.includes(targetDirection)) return 3;
  if (targetDirection.includes(direction.replace("방향", ""))) return 2;
  if (direction === "상하행") return 1;
  return 0;
}

function getOperatorCandidateKey(station) {
  return station.public_operator_id || station.operator_name || station.operator || station.station_id || "operator";
}

function getStationGroupKey(station) {
  return [station.highway_name, station.service_area_name, Math.round(station.position_ratio * 1000)].join("|");
}

function rawAvailableCount(station) {
  const value = Number(station?.public_available_charger_count);
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function rawChargingSpeed(station) {
  const raw = station?.public_max_output_kw || station?.public_output_kw || station?.charging_speed_kw || "";
  const value = Number(String(raw).replace(/[^0-9.]/g, ""));
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function scoreOperatorCandidate(candidate, group, targetDirection) {
  const prices = group.map((station) => Number(station.price_per_kwh)).filter(Number.isFinite);
  const lowestPrice = prices.length ? Math.min(...prices) : LOWEST_PRICE;
  const availableCounts = group.map(rawAvailableCount);
  const maxAvailable = Math.max(0, ...availableCounts);
  const speeds = group.map(rawChargingSpeed);
  const maxSpeed = Math.max(0, ...speeds);
  const price = Number(candidate.price_per_kwh);
  const priceDiff = Number.isFinite(price) ? price - lowestPrice : Infinity;
  const available = rawAvailableCount(candidate);
  const speed = rawChargingSpeed(candidate);
  const priceScore = priceDiff === 0 ? 3 : priceDiff <= 10 ? 1 : 0;
  const availableScore = maxAvailable > 0 && available === maxAvailable ? 3 : available >= 1 ? 2 : 0;
  const speedScore = maxSpeed > 0 && speed === maxSpeed ? 2 : speed >= 200 ? 1 : 0;
  return {
    price,
    available,
    speed,
    score: priceScore + availableScore + speedScore,
    direction: directionScore(candidate, targetDirection)
  };
}

function selectDisplayOperatorCandidate(group, targetDirection) {
  return group
    .map((station, index) => ({ station, index, metrics: scoreOperatorCandidate(station, group, targetDirection) }))
    .sort((a, b) =>
      b.metrics.score - a.metrics.score ||
      a.metrics.price - b.metrics.price ||
      b.metrics.available - a.metrics.available ||
      b.metrics.speed - a.metrics.speed ||
      b.metrics.direction - a.metrics.direction ||
      a.station.schematic_order - b.station.schematic_order ||
      a.index - b.index
    )[0]?.station || group[0];
}

function buildStationWithOperatorCandidates(group, targetDirection) {
  const displayCandidate = selectDisplayOperatorCandidate(group, targetDirection);
  const candidates = group
    .slice()
    .sort((a, b) => String(getOperatorCandidateKey(a)).localeCompare(String(getOperatorCandidateKey(b))))
    .map((station) => ({ ...station, operatorRecommendation: scoreOperatorCandidate(station, group, targetDirection) }));
  return {
    ...displayCandidate,
    operatorCandidates: candidates,
    displayOperatorCandidate: { ...displayCandidate, operatorRecommendation: scoreOperatorCandidate(displayCandidate, group, targetDirection) }
  };
}

function filterStationsByTravelDirection(stations, targetDirection) {
  const byRestArea = stations.reduce((groups, station) => {
    const key = getStationGroupKey(station);
    const group = groups.get(key) || [];
    group.push(station);
    groups.set(key, group);
    return groups;
  }, new Map());

  return [...byRestArea.values()].map((restAreaGroup) => {
    const byOperator = restAreaGroup.reduce((groups, station) => {
      const key = getOperatorCandidateKey(station);
      const group = groups.get(key) || [];
      group.push(station);
      groups.set(key, group);
      return groups;
    }, new Map());
    const operatorRepresentatives = [...byOperator.values()].map((operatorGroup) =>
      operatorGroup
        .slice()
        .sort((a, b) =>
          directionScore(b, targetDirection) - directionScore(a, targetDirection) ||
          a.price_per_kwh - b.price_per_kwh ||
          a.schematic_order - b.schematic_order
        )[0]
    );
    return buildStationWithOperatorCandidates(operatorRepresentatives, targetDirection);
  });
}

function computeRouteStations() {
  const start = getWaypointRatio(state.highway, state.origin);
  const end = getWaypointRatio(state.highway, state.destination);
  if (start === null || end === null) {
    state.routeStations = [];
    return;
  }
  const min = Math.min(start, end);
  const max = Math.max(start, end);
  state.routeStations = filterStationsByTravelDirection(state.stations
    .filter((station) => station.highway_name === state.highway)
    .filter((station) => station.position_ratio >= min - 0.04 && station.position_ratio <= max + 0.04)
    .sort((a, b) => a.position_ratio - b.position_ratio || a.schematic_order - b.schematic_order), state.destination);
  if (start > end) state.routeStations.reverse();
  window.__debugRouteStations = state.routeStations;
  selectInitialFocusedStation();
}


function selectInitialFocusedStation() {
  if (!state.routeStations.length) {
    state.focusedIndex = 0;
    return;
  }
  const recommended = getRecommendedStation();
  const recommendedIndex = recommended ? state.routeStations.indexOf(recommended) : -1;
  if (recommendedIndex >= 0) {
    state.focusedIndex = recommendedIndex;
    return;
  }
  const lowestPrice = getRouteLowestPrice();
  const lowestIndex = state.routeStations.findIndex((station) => Number(station?.price_per_kwh) === lowestPrice);
  state.focusedIndex = Math.max(0, lowestIndex);
}

function renderPinTotalBadge() {
  if (!els.pinTotalBadge || !els.pinTotalText) return;
  const count = state.routeStations.length;
  const selected = count > 0 ? Math.min(count, Math.max(1, state.focusedIndex + 1)) : 0;
  els.pinTotalText.textContent = selected + "/" + count;
  els.pinTotalBadge.hidden = count <= 0;
}

function render() {
  els.originValue.textContent = state.origin || "출발지";
  els.destinationValue.textContent = state.destination || "도착지";
  els.originTrigger.setAttribute("aria-label", `출발지 ${state.origin || "선택"}`);
  els.destinationTrigger.setAttribute("aria-label", `도착지 ${state.destination || "선택"}`);

  state.highway = findHighway(state.origin, state.destination);
  if (!state.highway) {
    els.routeLayer.innerHTML = "";
    els.stationLayer.innerHTML = '<div class="no-route-message">출발지와 도착지를 선택해 주세요.</div>';
    if (els.routeBadge) els.routeBadge.hidden = true;
    els.priceCard.hidden = true;
    if (els.brandLabel) els.brandLabel.hidden = true;
    if (els.pinTotalBadge) els.pinTotalBadge.hidden = true;
    setRouteEndsHidden(true);
    return;
  }

  computeRouteStations();
  const points = routeVisualPoints(state.highway);
  const start = getWaypointRatio(state.highway, state.origin) ?? 0;
  const end = getWaypointRatio(state.highway, state.destination) ?? 1;
  const segment = routeSegmentPoints(points, start, end);
  els.routeLayer.innerHTML = `<path class="route-shadow" d="${svgPath(insetRouteStroke(segment, 5))}" transform="translate(2 2)"></path><path class="route-main" d="${svgPath(insetRouteStroke(segment, 1.5))}"></path><path class="route-dash" d="${svgPath(insetRouteStroke(segment, 6))}"></path>`;
  renderRouteEnds(points, start, end);
  if (els.routeBadge) {
    els.routeBadge.textContent = state.highway;
    els.routeBadge.hidden = false;
  }
  els.priceCard.hidden = false;
  renderPinTotalBadge();
  renderDetail();
  renderStations(points);
}



function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function setRouteEndsHidden(hidden) {
  [els.startFlag, els.endFlag, els.startLabel, els.endLabel].forEach((node) => {
    if (node) node.hidden = hidden;
  });
}

function placeRouteEnd(flag, label, point, name, points, stationPoints, occupiedRects) {
  if (!flag || !label) return;
  const [x, y] = point;
  const city = flag === els.startFlag ? state.origin : state.destination;
  const layout = window.FIGMA_CITY_PIN_LAYOUT;
  const spec = layout && layout.cities[city] ? layout.flag : null;
  const flagLeft = spec ? x - spec.anchorX : clamp(x - FLAG_POLE_OFFSET_X, 18, 340);
  const flagTop = spec ? y - spec.anchorY : clamp(y - FLAG_TOP_OFFSET_Y, 248, 664);
  const flagHeight = spec ? spec.height : 37;
  flag.style.height = `${flagHeight}px`;
  const flagRect = { left: flagLeft, top: flagTop, right: flagLeft + 24, bottom: flagTop + flagHeight };

  flag.hidden = false;
  label.hidden = false;
  flag.alt = name;
  flag.style.left = `${flagLeft}px`;
  flag.style.top = `${flagTop}px`;
  label.textContent = name;
  const labelRect = chooseCityLabelRect(flagRect, name, points, stationPoints, occupiedRects);
  label.style.left = `${Math.round(labelRect.left)}px`;
  label.style.top = `${Math.round(labelRect.top)}px`;
  occupiedRects.push(padRect(flagRect, 3), padRect(labelRect, 2));
}

function renderRouteEnds(points, start, end) {
  const startPoint = pointOnPath(points, start);
  const endPoint = pointOnPath(points, end);
  const stationPoints = getRouteStationPoints(points);
  const occupiedRects = [];
  setRouteEndsHidden(false);
  placeRouteEnd(els.startFlag, els.startLabel, startPoint, "출발", points, stationPoints, occupiedRects);
  placeRouteEnd(els.endFlag, els.endLabel, endPoint, "도착", points, stationPoints, occupiedRects);
}

function chooseCityLabelRect(flagRect, name, points, stationPoints, occupiedRects) {
  const size = getCityLabelSize(name);
  const candidates = [
    { side: "left", left: flagRect.left - CITY_LABEL_GAP - size.width, top: flagRect.top + 20 },
    { side: "right", left: flagRect.right + CITY_LABEL_GAP, top: flagRect.top + 20 },
    { side: "bottom", left: flagRect.left + 12 - size.width / 2, top: flagRect.bottom + CITY_LABEL_GAP + 2 },
    { side: "top", left: flagRect.left + 12 - size.width / 2, top: flagRect.top - CITY_LABEL_GAP - size.height - 2 },
    { side: "left-high", left: flagRect.left - CITY_LABEL_GAP - size.width, top: flagRect.top - 2 },
    { side: "right-high", left: flagRect.right + CITY_LABEL_GAP, top: flagRect.top - 2 }
  ];

  return candidates
    .map((candidate, index) => {
      const rect = clampCityLabelRect(candidate, size);
      return { ...rect, score: cityLabelCollisionScore(rect, flagRect, points, stationPoints, occupiedRects) + index * 0.01 };
    })
    .sort((a, b) => a.score - b.score)[0];
}

function getCityLabelSize(name) {
  return {
    width: Math.max(35, String(name || "").length * 17 + 3),
    height: 19
  };
}

function clampCityLabelRect(rect, size) {
  const left = clamp(rect.left, CITY_LABEL_BOUNDS.left, CITY_LABEL_BOUNDS.right - size.width);
  const top = clamp(rect.top, CITY_LABEL_BOUNDS.top, CITY_LABEL_BOUNDS.bottom - size.height);
  return {
    left,
    top,
    right: left + size.width,
    bottom: top + size.height
  };
}

function cityLabelCollisionScore(rect, flagRect, points, stationPoints, occupiedRects) {
  let score = 0;
  if (rectsOverlap(rect, padRect(flagRect, 10))) score += 1200;
  occupiedRects.forEach((occupied) => {
    if (rectsOverlap(rect, padRect(occupied, 4))) score += 900;
  });
  getCityLabelUiCollisionRects().forEach((uiRect) => {
    if (rectsOverlap(rect, uiRect)) score += 5200;
  });
  stationPoints.forEach((point) => {
    const isFocused = point.index === state.focusedIndex;
    if (rectsOverlap(rect, padRect(getPinBox(point), isFocused ? 28 : 16))) score += isFocused ? 2600 : 700;
  });
  sampleRoutePoints(points).forEach(([x, y]) => {
    if (pointInRect(x, y, rect, 9)) score += 80;
  });
  return score;
}

function renderStations(points) {
  els.stationLayer.innerHTML = "";
  if (!state.routeStations.length) {
    if (els.brandLabel) els.brandLabel.hidden = true;
    return;
  }
  renderDetail();
  renderPinTotalBadge();
  const stationPoints = getRouteStationPoints(points);
  const renderOrder = state.routeStations.map((station, index) => ({ station, index })).sort((a, b) => (a.index === state.focusedIndex ? 1 : 0) - (b.index === state.focusedIndex ? 1 : 0));
  renderOrder.forEach(({ station, index }) => {
    const { x, y } = stationPoints[index];
    const isRecommended = isRecommendedStation(station);
    const isLowestPrice = isLowestPriceStation(station);
    const isWater = isWaterStation(station);
    const isFocused = index === state.focusedIndex;
    const button = document.createElement("button");
    button.type = "button";
    button.className = [
      "station-pin",
      isRecommended ? "is-recommended" : "",
      isFocused ? "is-focused" : ""
    ].filter(Boolean).join(" ");
    button.style.left = `${x}px`;
    button.style.top = `${y}px`;
    button.setAttribute("aria-label", `${station.service_area_name} ${station.price_per_kwh == null ? '요금 정보 없음' : station.price_per_kwh + '원'}`);
    button.setAttribute("aria-current", isFocused ? "true" : "false");
    if (isRecommended && isFocused) {
      const effect = document.createElement("img");
      effect.alt = "";
      effect.className = "pin-effect";
      effect.src = ASSETS.pinRecommendedSelectEffect;
      button.append(effect);
      appendCoinMotion(button);
    }
    const image = document.createElement("img");
    image.alt = "";
    image.className = "pin-image";
    image.src = getPinSrc(isRecommended, isLowestPrice, isWater);
    button.append(image);
    button.addEventListener("click", () => {
      state.focusedIndex = index;
      renderStations(points);
    });
    if (!isFocused) button.style.opacity = "0.92";
    els.stationLayer.append(button);
  });
  renderBrandLabel(points, stationPoints);
  els.prev.disabled = state.focusedIndex <= 0;
  els.next.disabled = state.focusedIndex >= state.routeStations.length - 1;
}

function renderBrandLabel(points, stationPoints) {
  const box = els.selectedDetailBox || els.brandLabel;
  if (!box) return;
  const focused = stationPoints[state.focusedIndex];
  if (!focused) {
    box.hidden = true;
    return;
  }

  const station = focused.station;
  if (els.detailOperator) els.detailOperator.textContent = detailFallback(getStationDisplayOperator(station));
  if (els.detailSpeed) els.detailSpeed.textContent = formatSelectedDetailSpeed(station);
  if (els.detailCount) els.detailCount.textContent = formatDetailCount(station);

  const isRecommended = isRecommendedStation(station);
  box.classList.toggle("is-recommended", isRecommended);
  box.classList.toggle("is-default", !isRecommended);
  const rect = chooseBrandLabelRect(points, stationPoints, focused);
  box.style.left = `${Math.round(rect.left)}px`;
  box.style.top = `${Math.round(rect.top)}px`;
  box.hidden = false;
}

function formatSelectedDetailSpeed(station) {
  const speed = formatDetailSpeed(station);
  if (speed === "--") return "--";
  return /^최대/.test(speed) ? speed : "최대 " + speed;
}

function chooseBrandLabelRect(points, stationPoints, focused) {
  const pinBox = getPinBox(focused);
  const centerTop = focused.y - BRAND_LABEL_SIZE.height / 2;
  const candidates = [
    { side: "safe-left", left: pinBox.left - BRAND_LABEL_GAP - BRAND_LABEL_SIZE.width, top: centerTop },
    { side: "safe-left-upper", left: pinBox.left - BRAND_LABEL_GAP - BRAND_LABEL_SIZE.width, top: pinBox.top - 44 },
    { side: "safe-left-lower", left: pinBox.left - BRAND_LABEL_GAP - BRAND_LABEL_SIZE.width, top: pinBox.bottom + 22 },
    { side: "map-left-empty", left: 18, top: focused.y - 74 },
    { side: "map-left-low", left: 18, top: focused.y + 46 },
    { side: "safe-right", left: pinBox.right + BRAND_LABEL_GAP, top: centerTop },
    { side: "safe-right-upper", left: pinBox.right + BRAND_LABEL_GAP, top: pinBox.top - 44 },
    { side: "safe-right-lower", left: pinBox.right + BRAND_LABEL_GAP, top: pinBox.bottom + 22 },
    { side: "map-right-empty", left: 375 - 18 - BRAND_LABEL_SIZE.width, top: focused.y - 74 },
    { side: "top-clear", left: focused.x - BRAND_LABEL_SIZE.width / 2, top: pinBox.top - BRAND_LABEL_GAP - BRAND_LABEL_SIZE.height },
    { side: "bottom-clear", left: focused.x - BRAND_LABEL_SIZE.width / 2, top: pinBox.bottom + BRAND_LABEL_GAP }
  ];

  return candidates
    .map((candidate, index) => {
      const rect = clampBrandLabelRect(candidate);
      return { ...rect, side: candidate.side, score: brandLabelCollisionScore(rect, points, stationPoints, focused, candidate.side) + index * 0.01 };
    })
    .sort((a, b) => a.score - b.score)[0];
}

function clampBrandLabelRect(rect) {
  const left = clamp(rect.left, BRAND_LABEL_BOUNDS.left, BRAND_LABEL_BOUNDS.right - BRAND_LABEL_SIZE.width);
  const top = clamp(rect.top, BRAND_LABEL_BOUNDS.top, BRAND_LABEL_BOUNDS.bottom - BRAND_LABEL_SIZE.height);
  return {
    left,
    top,
    right: left + BRAND_LABEL_SIZE.width,
    bottom: top + BRAND_LABEL_SIZE.height
  };
}

function brandLabelCollisionScore(rect, points, stationPoints, focused, side) {
  let score = 0;
  const safeRect = padRect(rect, 10);
  const focusedPinBox = getPinBox(focused);

  if (rectsOverlap(safeRect, padRect(focusedPinBox, 22))) score += 9000;

  stationPoints.forEach((point) => {
    const pinPad = point.index === focused.index ? 22 : 16;
    if (rectsOverlap(safeRect, padRect(getPinBox(point), pinPad))) score += point.index === focused.index ? 9000 : 3600;
  });

  sampleRoutePointsDense(points).forEach(([x, y]) => {
    if (pointInRect(x, y, safeRect, 20)) score += 900;
  });

  getRouteEndCollisionRects().forEach((endRect) => {
    if (rectsOverlap(safeRect, padRect(endRect, 8))) score += 4200;
  });

  getStaticUiCollisionRects().forEach((uiRect) => {
    if (rectsOverlap(safeRect, uiRect)) score += 12000;
  });

  // 좌측을 선호하되, 겹치지 않는 것이 최우선이다.
  if (side.includes("left")) score -= 260;
  if (side.includes("right")) score -= 60;
  if (side.includes("clear")) score += 120;

  // 화면 가장자리와 너무 붙으면 감점.
  if (rect.left <= 18 || rect.right >= 357) score += 180;

  return score;
}

function sampleRoutePointsDense(points) {
  return Array.from({ length: 72 }, (_, index) => pointOnPath(points, index / 71));
}

function getCityLabelUiCollisionRects() {
  const rects = [];
  const selectedBox = els.selectedDetailBox || els.brandLabel;
  const selectedRect = rectFromPositionedNode(selectedBox, BRAND_LABEL_SIZE.width, BRAND_LABEL_SIZE.height);
  if (selectedRect) rects.push(padRect(selectedRect, 18));

  const badge = getPinTotalBadgeCollisionRect() || getPinTotalBadgePlannedCollisionRect();
  if (badge) rects.push(padRect(badge, 8));

  getStaticUiCollisionRects().forEach((rect) => rects.push(rect));
  return rects;
}

function getPinTotalBadgePlannedCollisionRect() {
  return { left: 4, top: 600, right: 146, bottom: 710 };
}

function getStaticUiCollisionRects() {
  const rects = [
    { left: 18, top: 124, right: 357, bottom: 316 },
    { left: 22, top: 133, right: 356, bottom: 190 },
    { left: 18, top: 211, right: 358, bottom: 292 },
    { left: 16, top: 676, right: 364, bottom: 736 }
  ];

  const badgeRect = getPinTotalBadgeCollisionRect();
  if (badgeRect) rects.push(badgeRect);

  return rects.map((rect) => padRect(rect, 10));
}

function getPinTotalBadgeCollisionRect() {
  const badge = els.pinTotalBadge;
  if (!badge || badge.hidden) return null;

  const inlineRect = rectFromPositionedNode(badge, 86, 48);
  if (inlineRect) return padRect(inlineRect, 18);

  const screen = els.mapScreen || document.querySelector(".figma-screen");
  const badgeClient = badge.getBoundingClientRect?.();
  const screenClient = screen?.getBoundingClientRect?.();
  if (badgeClient && screenClient && badgeClient.width && badgeClient.height) {
    return padRect({
      left: badgeClient.left - screenClient.left,
      top: badgeClient.top - screenClient.top,
      right: badgeClient.right - screenClient.left,
      bottom: badgeClient.bottom - screenClient.top
    }, 18);
  }

  return { left: 8, top: 610, right: 132, bottom: 718 };
}

function getRouteEndCollisionRects() {
  const rects = [];
  [els.startFlag, els.endFlag].forEach((flag) => {
    const rect = rectFromPositionedNode(flag, 24, 52);
    if (rect) rects.push(padRect(rect, 4));
  });
  [els.startLabel, els.endLabel].forEach((label) => {
    const width = Math.max(36, (label?.textContent || "").length * 18);
    const rect = rectFromPositionedNode(label, width, 28);
    if (rect) rects.push(padRect(rect, 3));
  });
  return rects;
}

function rectFromPositionedNode(node, width, height) {
  if (!node || node.hidden) return null;
  const left = Number.parseFloat(node.style.left);
  const top = Number.parseFloat(node.style.top);
  if (!Number.isFinite(left) || !Number.isFinite(top)) return null;
  return { left, top, right: left + width, bottom: top + height };
}

function padRect(rect, padding) {
  return {
    left: rect.left - padding,
    top: rect.top - padding,
    right: rect.right + padding,
    bottom: rect.bottom + padding
  };
}

function getPinBox(point) {
  const focused = point.index === state.focusedIndex;
  const width = focused ? 30 : 15;
  const height = focused ? 45 : 23;
  const left = point.x - width / 2;
  const top = point.y - height * 0.88;
  return { left, top, right: left + width, bottom: top + height };
}

function sampleRoutePoints(points) {
  return Array.from({ length: 24 }, (_, index) => pointOnPath(points, index / 23));
}

function rectsOverlap(a, b) {
  return a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;
}

function pointInRect(x, y, rect, padding = 0) {
  return x >= rect.left - padding && x <= rect.right + padding && y >= rect.top - padding && y <= rect.bottom + padding;
}

function getOverlapGroups(stations) {
  return stations.reduce((groups, station, index) => {
    const key = `${station.highway_name}|${station.service_area_name}|${Math.round(station.position_ratio * 1000)}`;
    const group = groups.get(key) || [];
    group.push(index);
    groups.set(key, group);
    return groups;
  }, new Map());
}

function getRouteStationPoints(points) {
  const overlapGroups = getOverlapGroups(state.routeStations);
  return state.routeStations.map((station, index) => {
    const [x, y] = getStationPinPoint(points, station, index, overlapGroups);
    return { x, y, station, index };
  });
}

function getStationPinPoint(points, station, index, overlapGroups) {
  return pointOnPath(points, station.position_ratio);
}

function getRouteLowestPrice() {
  const prices = state.routeStations.map((station) => station.price_per_kwh).filter((price) => typeof price === 'number' && Number.isFinite(price));
  return prices.length ? Math.min(...prices) : null;
}

function isLowestPriceStation(station) {
  return typeof station?.price_per_kwh === 'number' && station.price_per_kwh === getRouteLowestPrice();
}

function getStationAvailableCount(station) {
  if (typeof stationPublicDetailsBelongToDisplayOperator === "function" && !stationPublicDetailsBelongToDisplayOperator(station)) return 0;
  return rawAvailableCount(station?.displayOperatorCandidate || station);
}

function getStationChargingSpeed(station) {
  if (typeof stationPublicDetailsBelongToDisplayOperator === "function" && !stationPublicDetailsBelongToDisplayOperator(station)) return 0;
  return rawChargingSpeed(station?.displayOperatorCandidate || station);
}

function getLowestPriceStations() {
  const lowestPrice = getRouteLowestPrice();
  return state.routeStations.filter((station) => Number(station?.price_per_kwh) === lowestPrice);
}

function getStationTotalCount(station) {
  const displayCandidate = station?.displayOperatorCandidate || station;
  const total = Number(displayCandidate?.public_total_charger_count || displayCandidate?.total_charger_count || displayCandidate?.charger_count);
  const available = Number(displayCandidate?.public_available_charger_count);
  if (Number.isFinite(total) && total > 0) return total;
  if (Number.isFinite(available) && available > 0) return available;
  return 0;
}

function getRouteDistanceScore(index, totalCount) {
  if (!Number.isFinite(index) || !Number.isFinite(totalCount) || totalCount <= 0) return 0;
  const firstMiddle = Math.floor((totalCount - 1) / 2);
  const secondMiddle = Math.ceil((totalCount - 1) / 2);
  if (index === firstMiddle || index === secondMiddle) return 2;
  if (Math.abs(index - firstMiddle) === 1 || Math.abs(index - secondMiddle) === 1) return 1;
  return 0;
}

function getChargerCountScore(total) {
  if (total >= 8) return 3;
  if (total >= 4) return 2;
  if (total >= 3) return 1;
  return 0;
}

function getChargingSpeedScore(speed) {
  if (speed >= 350) return 3;
  if (speed >= 200) return 2;
  if (speed >= 100) return 1;
  return 0;
}

function getRecommendedStation() {
  if (getExcelRoute()?.stops) return state.routeStations.find(station => station.excelRecommended) || null;
  const lowestStations = getLowestPriceStations();
  if (!lowestStations.length) return null;
  if (lowestStations.length === 1) return lowestStations[0];
  const routeCount = state.routeStations.length;

  return lowestStations
    .map((station) => {
      const index = state.routeStations.indexOf(station);
      const total = getStationTotalCount(station);
      const speed = getStationChargingSpeed(station);
      const distanceScore = getRouteDistanceScore(index, routeCount);
      const chargerScore = getChargerCountScore(total);
      const speedScore = getChargingSpeedScore(speed);
      return {
        station,
        index,
        total,
        speed,
        score: distanceScore + chargerScore + speedScore,
        distanceScore,
        chargerScore,
        speedScore
      };
    })
    .sort((a, b) =>
      b.score - a.score ||
      b.speed - a.speed ||
      b.total - a.total ||
      a.index - b.index
    )[0]?.station || lowestStations[0];
}

function isRecommendedStation(station) {
  return station === getRecommendedStation();
}

function isWaterStation(station) {
  const operator = String(station?.operator_name || station?.operatorName || station?.operator || "").toLowerCase();
  return operator.includes("워터") || operator.includes("water") || String(station?.station_id || "").startsWith("water_");
}

function getPinSrc(isRecommended, isLowestPrice, isWater) {
  if (isRecommended) return ASSETS.pinRecommended;
  if (isLowestPrice) return ASSETS.pinLowPrice || ASSETS.pinDefault;
  return ASSETS.pinDefault;
}

function appendCoinMotion(pin) {
  const coin = document.createElement("img");
  coin.alt = "";
  coin.className = "coin-motion";
  let frameIndex = 0;
  coin.src = `${ASSETS.coinMotionDir}/${COIN_MOTION_FRAMES[frameIndex].name}.png`;
  pin.append(coin);

  const timer = window.setInterval(() => {
    frameIndex += 1;
    if (frameIndex >= COIN_MOTION_FRAMES.length) {
      window.clearInterval(timer);
      coin.remove();
      return;
    }
    coin.src = `${ASSETS.coinMotionDir}/${COIN_MOTION_FRAMES[frameIndex].name}.png`;
  }, 82);
}


function getStationDisplayOperator(station) {
  if (!station) return "";
  const displayCandidate = station.displayOperatorCandidate || station;
  const baseOperator = displayCandidate.operator_name || displayCandidate.operator || (String(displayCandidate.station_id || "").startsWith("water_") ? "워터" : "");
  const publicOperator = displayCandidate.public_operator_name || "";
  const isWaterLowestSeed = Number(displayCandidate.price_per_kwh) === 294 && isWaterStation(displayCandidate);
  if (isWaterLowestSeed) return baseOperator || "워터";
  return publicOperator || baseOperator;
}

function stationPublicDetailsBelongToDisplayOperator(station) {
  const displayCandidate = station?.displayOperatorCandidate || station;
  const displayOperator = getStationDisplayOperator(displayCandidate);
  const publicOperator = displayCandidate?.public_operator_name || station?.public_operator_name || "";
  if (!publicOperator) return true;
  return publicOperator === displayOperator;
}

function detailFallback(value) {
  return value === undefined || value === null || String(value).trim() === "" ? "--" : String(value).trim();
}

function formatDetailSpeed(station) {
  const displayCandidate = station?.displayOperatorCandidate || station;
  const raw = stationPublicDetailsBelongToDisplayOperator(station) ? (displayCandidate.public_max_output_kw || displayCandidate.public_output_kw || displayCandidate.charging_speed_kw || "") : "";
  if (!raw) return "--";
  const textValue = String(raw).trim();
  if (!textValue) return "--";
  return /kw/i.test(textValue) ? textValue.replace(/kw/i, "kW") : textValue + "kW";
}

function formatDetailCount(station) {
  if (!stationPublicDetailsBelongToDisplayOperator(station)) return "--";
  if (!stationPublicDetailsBelongToDisplayOperator(station)) return "--";
  const displayCandidate = station?.displayOperatorCandidate || station;
  const total = Number(displayCandidate.public_total_charger_count || displayCandidate.total_charger_count || displayCandidate.charger_count);
  const available = Number(displayCandidate.public_available_charger_count);
  const fallbackCount = Number.isFinite(available) && available > 0 ? available : 0;
  const count = Number.isFinite(total) && total > 0 ? total : fallbackCount;
  if (!count) return "--";
  return "충전기수 " + count + "기";
}

function getDetailCardType(station) {
  if (isRecommendedStation(station)) return "recommended";
  if (isLowestPriceStation(station)) return "lowPrice";
  return "default";
}

function getDetailCardAsset(type) {
  return ASSETS.cardCommon || ASSETS.cardDefault;
}

function getDetailChargerAsset(type) {
  if (type === "recommended") return ASSETS.chargerRecommended;
  if (type === "lowPrice") return ASSETS.chargerLowPrice;
  return ASSETS.chargerDefault;
}

function stopDetailChargerMotion() {
  if (detailChargerMotionTimer) {
    window.clearInterval(detailChargerMotionTimer);
    detailChargerMotionTimer = null;
  }
  detailChargerMotionIndex = 0;
}

function setDetailChargerAsset(type) {
  if (!els.detailCharger) return;
  if (type !== "recommended") {
    stopDetailChargerMotion();
    els.detailCharger.src = getDetailChargerAsset(type);
    return;
  }
  const frames = EV_CHARGER_MOTION_FRAMES;
  if (!frames.length) {
    els.detailCharger.src = getDetailChargerAsset(type);
    return;
  }
  stopDetailChargerMotion();
  els.detailCharger.src = frames[0];
  detailChargerMotionTimer = window.setInterval(() => {
    detailChargerMotionIndex = (detailChargerMotionIndex + 1) % frames.length;
    els.detailCharger.src = frames[detailChargerMotionIndex];
  }, 420);
}

function ensureDetailLabelContainer() {
  let container = document.querySelector("#detailLabels");
  if (!container) {
    container = document.createElement("span");
    container.id = "detailLabels";
    container.className = "price-card-labels";
    els.detailLowPriceLabel?.replaceWith(container);
    els.detailLowPriceLabel = container;
  }
  return container;
}

function renderDetailLabels(station, type) {
  const container = ensureDetailLabelContainer();
  const lowestCount = getLowestPriceStations().length;
  const labels = [];
  if (type === "recommended") {
    labels.push({ src: ASSETS.labelLowPrice, alt: "최저가" });
    if (lowestCount > 1) labels.push({ src: ASSETS.labelRecommended, alt: "추천" });
  } else if (type === "lowPrice") {
    labels.push({ src: ASSETS.labelSharedLowPrice, alt: "공동 최저가" });
  }
  container.innerHTML = labels.map((label) => '<img src="' + label.src + '" alt="' + label.alt + '" />').join("");
  container.hidden = labels.length === 0;
}

function applyDetailCardType(station) {
  const type = getDetailCardType(station);
  els.priceCard.dataset.cardType = type;
  els.priceCard.classList.toggle("is-recommended", type === "recommended");
  els.priceCard.classList.toggle("is-low-price", type === "lowPrice");
  els.priceCard.classList.toggle("is-default", type === "default");
  const bg = els.priceCard.querySelector(".price-card-bg");
  if (bg) {
    bg.onerror = () => {
      if (type === "default" && bg.src.indexOf("defalut") < 0) bg.src = ASSETS.cardDefaultFallback;
    };
    bg.src = getDetailCardAsset(type);
  }
  setDetailChargerAsset(type);
  renderDetailLabels(station, type);
  return type;
}


function getHighwayShortLabel(highwayName) {
  const raw = String(highwayName || state.highway || "").trim();
  if (!raw) return "--";
  const label = raw.replace(/고속도로$/u, "").replace(/고속화도로$/u, "").replace(/선$/u, "");
  return label || raw;
}
function renderDetail() {
  const station = state.routeStations[state.focusedIndex];
  if (!station) {
    els.priceCard.hidden = true;
    return;
  }
  els.priceCard.hidden = false;
  applyDetailCardType(station);
  const detailPriceText = String(station.price_per_kwh ?? "--");
  const isShortDefaultPrice = getDetailCardType(station) === "default" && /^\d{1,3}$/.test(detailPriceText);
  els.priceCard.classList.toggle("is-price-short", isShortDefaultPrice);
  els.detailPrice.innerHTML = `<span class="detail-price-number">${detailPriceText}</span><span class="detail-price-unit">원</span>`;
  if (els.detailHighwayTag) els.detailHighwayTag.textContent = station.direction || "방향 미상";
  const upcoming = document.querySelector('#detailUpcoming');
  if (upcoming) upcoming.hidden = station.openingStatus !== '오픈예정';
  els.detailStation.textContent = station.service_area_name || "휴게소";
}

function moveFocus(delta) {
  if (!state.routeStations.length) return;
  state.focusedIndex = Math.max(0, Math.min(state.routeStations.length - 1, state.focusedIndex + delta));
  const points = routeVisualPoints(state.highway);
  renderStations(points);
}


// 2026-07-01 stable Excel data integration.
var EXCEL_ROUTE_DATA = window.APP_ROUTE_DATA || { originOptions: [], routes: [], stationDetails: [] };
var ORIGIN_REGION_ORDER = ["서울", "경기", "인천", "강원", "대전", "세종", "충북", "충남", "대구", "경북", "부산", "울산", "경남", "광주", "전북", "전남"];
var DESTINATION_REGION_ORDER = ["서울", "경기", "인천", "강릉", "속초", "대전", "세종", "청주", "제천", "충남", "대구", "안동", "포항", "부산", "울산", "창원", "통영", "광주", "전북", "전남"];

function sortByConfiguredRegionOrder(values, order) {
  return values.slice().sort(function(a, b) {
    var ai = order.indexOf(a);
    var bi = order.indexOf(b);
    if (ai < 0) ai = 999;
    if (bi < 0) bi = 999;
    return ai - bi || String(a).localeCompare(String(b), "ko");
  });
}

var EXCEL_STATION_INDEX = new Map();
var EXCEL_STATION_ROWS = new Map();
(EXCEL_ROUTE_DATA.stationDetails || []).forEach(function(station) {
  EXCEL_STATION_ROWS.set(station.sourceRow, station);
  var key = normalizeExcelKey(station.serviceAreaName);
  if (!EXCEL_STATION_INDEX.has(key)) EXCEL_STATION_INDEX.set(key, []);
  EXCEL_STATION_INDEX.get(key).push(station);
});

var FIXED_CITY_ROUTE_POINTS_FINAL = {
  // Coordinates are intentionally compressed into the visible map-safe area.
  // Keep all start/end flags below the top controls/card and above the bottom buttons.
  "서울": [136, 388], "인천": [104, 397], "경기": [150, 411],
  "강원": [252, 379], "강릉": [296, 386], "속초": [304, 355],
  "충북": [190, 459], "충남": [124, 470], "청주": [178, 462], "제천": [223, 444],
  "세종": [158, 484], "대전": [166, 502], "전북": [132, 544], "전남": [105, 600], "광주": [118, 585],
  "경북": [245, 491], "안동": [258, 464], "대구": [252, 534], "포항": [308, 520],
  "울산": [300, 578], "경남": [238, 599], "창원": [255, 612], "통영": [238, 640], "부산": [303, 623]
};

function normalizeExcelKey(value) {
  return String(value || "").replace(/[\s()]/g, "").replace(/휴게소/g, "").replace(/포도/g, "");
}

function getExcelRoute(origin, destination) {
  var o = origin === undefined ? state.origin : origin;
  var d = destination === undefined ? state.destination : destination;
  return (EXCEL_ROUTE_DATA.routes || []).find(function(route) { return route.origin === o && route.destination === d; }) || null;
}

function getOriginOptions() {
  return sortByConfiguredRegionOrder(
    (EXCEL_ROUTE_DATA.originOptions || []).filter(function(origin) { return getDestinationOptions(origin).length > 0; }),
    ORIGIN_REGION_ORDER
  );
}

function getDestinationOptions(origin) {
  return sortByConfiguredRegionOrder((EXCEL_ROUTE_DATA.routes || [])
    .filter(function(route) { return route.origin === origin && Array.isArray(route.restAreas) && route.restAreas.length > 0; })
    .map(function(route) { return route.destination; })
    .filter(function(value, index, array) { return value && array.indexOf(value) === index; }), DESTINATION_REGION_ORDER);
}

function findHighway(origin, destination) {
  var route = getExcelRoute(origin, destination);
  return route ? route.highway : "";
}

function getCityRoutePoint(city) {
  var layout = window.FIGMA_CITY_PIN_LAYOUT;
  var pin = layout && layout.cities[city];
  if (!pin) return FIXED_CITY_ROUTE_POINTS_FINAL[city];
  var map = document.querySelector("#mapScreen .map");
  var rect = map && map.offsetWidth ? {
    left: map.offsetLeft, top: map.offsetTop, width: map.offsetWidth, height: map.offsetHeight
  } : layout.map;
  return [rect.left + pin.x * rect.width, rect.top + pin.y * rect.height];
}

function makeFixedRoutePointsFinal(route) {
  var start = getCityRoutePoint(route && route.origin);
  var end = getCityRoutePoint(route && route.destination);
  if (!start || !end) return null;
  var dx = end[0] - start[0];
  var dy = end[1] - start[1];
  var distance = Math.hypot(dx, dy) || 1;
  var bend = Math.min(28, Math.max(8, distance * 0.08));
  var normal = [-dy / distance, dx / distance];
  var curveSign = start[0] <= end[0] ? -1 : 1;
  var mid = [(start[0] + end[0]) / 2 + normal[0] * bend * curveSign, (start[1] + end[1]) / 2 + normal[1] * bend * curveSign];
  return [start, mid, end];
}

function routeVisualPoints(highway) {
  var route = getExcelRoute();
  var fixedPoints = route && route.highway === highway ? makeFixedRoutePointsFinal(route) : null;
  if (fixedPoints) return fixedPoints;
  var points = ROUTE_PATHS[highway] || ROUTE_PATHS["경부고속도로"];
  return points.map(function(point) { return [point[0], point[1] + ROUTE_VISUAL_OFFSET_Y]; });
}

function getHighwayPoints(highway) {
  var route = getExcelRoute();
  if (route && route.highway === highway) {
    return [
      { highway_name: highway, waypoint_name: route.origin, display_order: 0 },
      { highway_name: highway, waypoint_name: route.destination, display_order: 1 }
    ];
  }
  return state.waypoints.filter(function(point) { return point.highway_name === highway; }).sort(function(a, b) { return a.display_order - b.display_order; });
}

function getWaypointRatio(highway, name) {
  var route = getExcelRoute();
  if (route && route.highway === highway) {
    if (name === route.origin) return 0;
    if (name === route.destination) return 1;
  }
  var points = getHighwayPoints(highway);
  var index = points.findIndex(function(point) { return point.waypoint_name === name; });
  if (index < 0 || points.length < 2) return null;
  return index / (points.length - 1);
}

function routeStationCount(highway, origin, destination) {
  var route = getExcelRoute(origin, destination);
  return route && route.restAreas ? route.restAreas.length : 0;
}

function getRouteStationRatio(route, index) {
  var count = route && route.restAreas ? route.restAreas.length : 0;
  if (!count) return 0.5;
  return Math.min(0.96, Math.max(0.04, (index + 1) / (count + 1)));
}

function getDisplayCandidateFromExcel(candidates, route) {
  var exactY = candidates.find(function(candidate) { return candidate.pinDisplay === "Y" && candidate.direction === route.travelDirection; });
  if (exactY) return exactY;
  var anyY = candidates.find(function(candidate) { return candidate.pinDisplay === "Y"; });
  if (anyY) return anyY;
  var exact = candidates.find(function(candidate) { return candidate.direction === route.travelDirection; });
  return exact || candidates[0] || null;
}

function convertExcelStation(candidate, allCandidates, route, index, total) {
  var ratio = getRouteStationRatio(route, index);
  var operatorCandidates = allCandidates.map(function(item) {
    return {
      station_id: "excel_" + item.sourceRow,
      highway_name: route.highway,
      highway_label: route.highwayLabel,
      service_area_name: item.serviceAreaName,
      direction: item.direction || route.travelDirection,
      operator_name: item.detailOperator || item.operatorDisplay,
      operator: item.detailOperator || item.operatorDisplay,
      price_per_kwh: item.price,
      charging_speed_kw: item.maxOutputKw || item.speedKw,
      public_max_output_kw: item.maxOutputKw || item.speedKw,
      total_charger_count: item.chargerCount,
      charger_count: item.chargerCount,
      detail_speed_label: item.detailSpeedLabel,
      detail_count_label: item.detailChargerCountLabel,
      lat: item.lat,
      lng: item.lng,
      pin_display: item.pinDisplay,
      source_row: item.sourceRow,
      source_data: item
    };
  });
  var displayCandidate = operatorCandidates.find(function(item) { return item.source_row === candidate.sourceRow; }) || operatorCandidates[0];
  return Object.assign({}, displayCandidate, {
    station_id: "route_" + route.origin + "_" + route.destination + "_" + index,
    highway_name: route.highway,
    highway_label: route.highwayLabel,
    service_area_name: candidate.serviceAreaName,
    direction: candidate.direction || route.travelDirection,
    position_ratio: ratio,
    schematic_order: index,
    operatorCandidates: operatorCandidates,
    displayOperatorCandidate: displayCandidate
  });
}

function computeRouteStations() {
  var route = getExcelRoute();
  if (!route) {
    state.routeStations = [];
    return;
  }
  var total = route.restAreas.length;
  if (route.stops) {
    state.routeStations = route.stops.map(function(stop, index) {
      var candidates = stop.candidateRows.map(row => EXCEL_STATION_ROWS.get(row)).filter(Boolean);
      var display = EXCEL_STATION_ROWS.get(stop.displayRow) || {
        sourceRow: 'unavailable_' + stop.sourceRow, serviceAreaName: stop.name,
        direction: stop.direction, price: null, openingStatus: '확인필요', operatorDisplay: '정보 없음'
      };
      var station = convertExcelStation(display, candidates, route, index, total);
      return Object.assign(station, {service_area_name:stop.name, direction:stop.direction,
        openingStatus:display.openingStatus, excelRecommended:stop.recommended,
        price_per_kwh:display.price, operator_name:display.detailOperator || display.operatorDisplay,
        sourceRow:stop.sourceRow});
    });
    window.__debugRouteStations = state.routeStations;
    selectInitialFocusedStation();
    return;
  }
  state.routeStations = route.restAreas.map(function(name, index) {
    var candidates = EXCEL_STATION_INDEX.get(normalizeExcelKey(name)) || [];
    var display = getDisplayCandidateFromExcel(candidates, route);
    if (!display) return null;
    return convertExcelStation(display, candidates, route, index, total);
  }).filter(Boolean);
  window.__debugRouteStations = state.routeStations;
  selectInitialFocusedStation();
}

function getStationDisplayOperator(station) {
  if (!station) return "";
  var displayCandidate = station.displayOperatorCandidate || station;
  return displayCandidate.operator_name || displayCandidate.operator || (displayCandidate.source_data && (displayCandidate.source_data.detailOperator || displayCandidate.source_data.operatorDisplay)) || "";
}

function formatDetailSpeed(station) {
  var displayCandidate = station && (station.displayOperatorCandidate || station);
  var explicit = displayCandidate && (displayCandidate.detail_speed_label || (displayCandidate.source_data && displayCandidate.source_data.detailSpeedLabel));
  if (explicit) return explicit.replace(/^최대\s*/u, "");
  var raw = displayCandidate && (displayCandidate.public_max_output_kw || displayCandidate.public_output_kw || displayCandidate.charging_speed_kw || "");
  if (!raw) return "--";
  var textValue = String(raw).trim();
  if (!textValue) return "--";
  return /kw/i.test(textValue) ? textValue.replace(/kw/i, "kW") : textValue + "kW";
}

function formatSelectedDetailSpeed(station) {
  var displayCandidate = station && (station.displayOperatorCandidate || station);
  var explicit = displayCandidate && (displayCandidate.detail_speed_label || (displayCandidate.source_data && displayCandidate.source_data.detailSpeedLabel));
  if (explicit) return explicit;
  var speed = formatDetailSpeed(station);
  if (speed === "--") return "--";
  return /^최대/.test(speed) ? speed : "최대 " + speed;
}

function formatDetailCount(station) {
  var displayCandidate = station && (station.displayOperatorCandidate || station);
  var explicit = displayCandidate && (displayCandidate.detail_count_label || (displayCandidate.source_data && displayCandidate.source_data.detailChargerCountLabel));
  if (explicit) return explicit;
  var total = Number(displayCandidate && (displayCandidate.total_charger_count || displayCandidate.charger_count));
  if (!Number.isFinite(total) || total <= 0) return "--";
  return "충전기수 " + total + "기";
}

function getHighwayShortLabel(highwayName) {
  var route = getExcelRoute();
  var raw = String((route && route.highwayLabel) || highwayName || state.highway || "").trim();
  if (!raw) return "--";
  var label = raw.replace(/고속도로$/u, "").replace(/고속화도로$/u, "").replace(/선$/u, "");
  return label || raw;
}

